// Image pipeline for Hotel Shantivan.
//
// Reads media/media-sources.json and produces:
//   public/assets/images/<id>.jpg          full-quality master (original bytes when no crop is needed)
//   public/assets/optimized/<id>-<w>.<fmt>  responsive AVIF / WebP / JPEG variants
//   public/assets/posters/<id>.{jpg,webp}   lightweight video posters
//   public/og-image.jpg                     1200×630 social share image
//   src/config/media.generated.ts           dimensions, variant widths and blur placeholders (do not edit)
//
// Video posters / stills come from media/.cache/stills, produced by scripts/process-videos.swift.

import { copyFile, mkdir, readFile, writeFile, access } from 'node:fs/promises'
import path from 'node:path'
import sharp from 'sharp'

const root = process.cwd()
const p = (...parts) => path.join(root, ...parts)
const exists = (file) => access(file).then(() => true, () => false)

const sources = JSON.parse(await readFile(p('media/media-sources.json'), 'utf8'))
const WIDTHS = [480, 640, 960]

for (const dir of ['public/assets/images', 'public/assets/optimized', 'public/assets/posters']) {
  await mkdir(p(dir), { recursive: true })
}

/** @type {Record<string, { width: number; height: number; widths: number[]; lqip: string }>} */
const images = {}
/** @type {Record<string, { width: number; height: number; duration?: number }>} */
const videos = {}

async function writeVariants(id, masterPath) {
  const meta = await sharp(masterPath).metadata()
  const widths = [...new Set([...WIDTHS.filter((w) => w < meta.width), meta.width])]
  for (const w of widths) {
    const base = sharp(masterPath).resize({ width: w, withoutEnlargement: true })
    await base.clone().avif({ quality: 52, effort: 6 }).toFile(p(`public/assets/optimized/${id}-${w}.avif`))
    await base.clone().webp({ quality: 76, effort: 6 }).toFile(p(`public/assets/optimized/${id}-${w}.webp`))
    await base.clone().jpeg({ quality: 80, mozjpeg: true }).toFile(p(`public/assets/optimized/${id}-${w}.jpg`))
  }
  const lqipBuffer = await sharp(masterPath).resize({ width: 16 }).blur(0.6).webp({ quality: 40 }).toBuffer()
  images[id] = {
    width: meta.width,
    height: meta.height,
    widths,
    lqip: `data:image/webp;base64,${lqipBuffer.toString('base64')}`,
  }
  console.log(`image  ${id}  ${meta.width}×${meta.height}  [${widths.join(', ')}]`)
}

// 1. Photographs supplied by the owner.
for (const image of sources.images) {
  const src = p('media/originals', image.source)
  const master = p(`public/assets/images/${image.id}.jpg`)
  if (image.crop) {
    await sharp(src).extract(image.crop).jpeg({ quality: 92, mozjpeg: true }).toFile(master)
  } else {
    await copyFile(src, master)
  }
  await writeVariants(image.id, master)
}

// 2. Stills grabbed from the videos (used as room / gallery photographs).
for (const still of sources.stills) {
  const src = p('media/.cache/stills', `${still.id}.jpg`)
  if (!(await exists(src))) {
    console.warn(`skip   ${still.id} (run scripts/process-videos.swift first)`)
    continue
  }
  const master = p(`public/assets/images/${still.id}.jpg`)
  await sharp(src).jpeg({ quality: 90, mozjpeg: true }).toFile(master)
  await writeVariants(still.id, master)
}

// 3. Video posters.
for (const video of sources.videos) {
  const src = p('media/.cache/stills', `${video.id}-poster.jpg`)
  if (!(await exists(src))) {
    console.warn(`skip   poster ${video.id}`)
    continue
  }
  const meta = await sharp(src).metadata()
  await sharp(src).jpeg({ quality: 74, mozjpeg: true }).toFile(p(`public/assets/posters/${video.id}.jpg`))
  await sharp(src).webp({ quality: 70 }).toFile(p(`public/assets/posters/${video.id}.webp`))
  videos[video.id] = { width: meta.width, height: meta.height }
  console.log(`poster ${video.id}  ${meta.width}×${meta.height}`)
}

// 4. Open Graph share image — a triptych of genuine hotel photographs.
const triptych = ['exterior-entrance-day', 'room-mist', 'garden-lights-night']
const panels = await Promise.all(
  triptych.map((id) =>
    sharp(p(`public/assets/images/${id}.jpg`)).resize(396, 630, { fit: 'cover', position: 'attention' }).toBuffer(),
  ),
)
await sharp({ create: { width: 1200, height: 630, channels: 3, background: '#244A36' } })
  .composite(panels.map((input, i) => ({ input, left: i * 402, top: 0 })))
  .jpeg({ quality: 82, mozjpeg: true })
  .toFile(p('public/og-image.jpg'))
console.log('og     public/og-image.jpg')

// 5. Typed manifest consumed by src/config/media.ts.
const banner = '// AUTO-GENERATED by scripts/optimize-media.mjs — do not edit by hand.\n'
await writeFile(
  p('src/config/media.generated.ts'),
  `${banner}\nexport const imageMeta = ${JSON.stringify(images, null, 2)} as const\n\nexport const videoMeta = ${JSON.stringify(videos, null, 2)} as const\n\nexport type ImageId = keyof typeof imageMeta\nexport type VideoId = keyof typeof videoMeta\n`,
)
console.log('wrote  src/config/media.generated.ts')
